{
  "initiative": "Migrate reporting stack off legacy platform within the next planning period",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Assess current reporting architecture and dependencies",
      "owner_role": "Platform Engineering Lead",
      "duration_quarters": 1,
      "deliverable": "Comprehensive inventory and dependency map of reporting components and interfaces"
    },
    {
      "id": "WP-02",
      "title": "Define target architecture and migration plan",
      "owner_role": "Enterprise Architect",
      "duration_quarters": 1,
      "deliverable": "Target architecture diagram and migration control checklist"
    },
    {
      "id": "WP-03",
      "title": "Design and build migration tools and scripts",
      "owner_role": "Systems Engineering Manager",
      "duration_quarters": 1,
      "deliverable": "Migration scripts, configuration templates and test harness for reporting components"
    },
    {
      "id": "WP-04",
      "title": "Execute phased cutover and verification",
      "owner_role": "Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Cutover execution records, verification reports and non-conformance log"
    },
    {
      "id": "WP-05",
      "title": "Post-migration validation and remediation",
      "owner_role": "Quality Assurance Lead",
      "duration_quarters": 1,
      "deliverable": "Validation report, remediation plan and final sign-off package"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1: Readiness and Risk Acceptance",
      "approver_role": "Program Steering Committee Chair",
      "criteria": "Completed inventory, dependency map, and documented control checklist; risk register accepted and mitigation defined"
    },
    {
      "gate": "G2",
      "name": "Gate 2: Technical Design and Test Plan Approval",
      "approver_role": "Chief Technology Officer",
      "criteria": "Target architecture approved, migration scripts tested in test harness, and test plan accepted for cutover"
    },
    {
      "gate": "G3",
      "name": "Gate 3: Pre-Cutover Readiness",
      "approver_role": "Operations Director",
      "criteria": "Migration tools deployed, cutover checklist complete, and non-conformance items logged with remediation plans"
    },
    {
      "gate": "G4",
      "name": "Gate 4: Final Sign-off and Closeout",
      "approver_role": "Quality and Compliance Director",
      "criteria": "Post-migration validation report accepted, all deviations addressed, and formal sign-off on deliverable acceptance"
    }
  ],
  "compliance_notes": [
    "All activities will follow the corporate change control procedure and be recorded in the configuration management system.",
    "Any non-conformance discovered during cutover must be logged, triaged and escalated per the quality management process."
  ],
  "risks": [
    {
      "risk": "Undiscovered dependencies cause migration failures",
      "mitigation": "Perform comprehensive discovery in WP-01, include contingency tests and maintain rollback plan; escalate at gate review if risk exceeds threshold",
      "severity": "high"
    },
    {
      "risk": "Resource constraints delay migration execution",
      "mitigation": "Prioritise critical components, allocate resources in WP-03 and WP-04, and include resource contingency in schedule",
      "severity": "medium"
    },
    {
      "risk": "Data integrity issues during cutover",
      "mitigation": "Implement staged cutover, perform verification in WP-04, and maintain backups with checksums; require verification sign-off before final closeout",
      "severity": "high"
    }
  ],
  "timeline_horizon": "One planning period (four consecutive quarters aligned to the next planning period horizon)"
}

{
  "initiative": "Reduce energy intensity 30% at two highest-consuming sites through targeted efficiency and control actions",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Baseline assessment and energy audit of the two sites",
      "owner_role": "Site Energy Engineer",
      "duration_quarters": 1,
      "deliverable": "Detailed baseline report and audited energy consumption per unit, including identified deviations and non-conformance log"
    },
    {
      "id": "WP-02",
      "title": "Design and control improvement plan for high-energy processes",
      "owner_role": "Process Engineering Lead",
      "duration_quarters": 1,
      "deliverable": "Process control retrofit design package and control improvement list with expected energy reduction per process"
    },
    {
      "id": "WP-03",
      "title": "Implementation of selected measures and equipment upgrades",
      "owner_role": "Capital Projects Manager",
      "duration_quarters": 2,
      "deliverable": "Installed and commissioned energy-efficient equipment, commissioning report, and updated process control documents"
    },
    {
      "id": "WP-04",
      "title": "Operational monitoring, training and performance verification",
      "owner_role": "Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Operational monitoring dashboard, training records, and quarterly performance verification report demonstrating energy reduction"
    },
    {
      "id": "WP-05",
      "title": "Sustainment plan and continuous improvement loop",
      "owner_role": "Maintenance Superintendent",
      "duration_quarters": 2,
      "deliverable": "Sustainment plan, corrective action process, and schedule for routine audits to prevent regression"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1 - Readiness to design",
      "approver_role": "Site General Manager",
      "criteria": "Baseline report accepted, deviations logged, and design package reviewed for feasibility; no outstanding non-conformance above low severity"
    },
    {
      "gate": "G2",
      "name": "Gate 2 - Procurement and capital approval",
      "approver_role": "Capital Budget Committee Chair",
      "criteria": "Design package approved, cost estimate and control measures signed-off, and procurement readiness confirmed"
    },
    {
      "gate": "G3",
      "name": "Gate 3 - Commissioning and operational handover",
      "approver_role": "Operations Director",
      "criteria": "Commissioning report completed, performance verification criteria met, training completed, and handover sign-off executed"
    },
    {
      "gate": "G4",
      "name": "Gate 4 - Sustainment acceptance",
      "approver_role": "Head of Compliance",
      "criteria": "Sustainment plan accepted, corrective action process in place, and audit schedule approved with control limits defined"
    }
  ],
  "compliance_notes": [
    "All activities will follow regulated change control and document management procedures; deviations must be recorded and justified.",
    "Energy measurement and reporting will comply with corporate metering standards and internal audit requirements.",
    "Non-conformance handling procedures will be applied to any measured shortfall from the 30% target."
  ],
  "risks": [
    {
      "risk": "Measured energy reduction falls short of 30% due to underestimated process variability",
      "mitigation": "Include statistical confidence intervals in baseline, perform early pilot on high-impact process changes, and escalate unresolved deviations at gate review",
      "severity": "high"
    },
    {
      "risk": "Supply chain delays for critical equipment extend capital realization",
      "mitigation": "Qualify multiple suppliers, include lead-time buffers in procurement plan, and maintain a contingency inventory",
      "severity": "medium"
    },
    {
      "risk": "Operational resistance to new controls and procedures reduces effectiveness",
      "mitigation": "Engage site leadership early, deliver targeted training, and document control requirements in process handover",
      "severity": "medium"
    },
    {
      "risk": "Data integrity issues in energy measurement could misrepresent performance",
      "mitigation": "Implement metering validation protocol, periodic audits, and cross-check with third-party verification during commissioning",
      "severity": "low"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Increase utilisation of newest equipment to 98% of rated capacity",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Baseline assessment and data integrity validation",
      "owner_role": "Process Improvement Lead",
      "duration_quarters": 1,
      "deliverable": "Validated baseline report with equipment capacity, throughput metrics, and identified deviations"
    },
    {
      "id": "WP-02",
      "title": "Operational control adjustments and procedure updates",
      "owner_role": "Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Revised operating procedures, control checklists and training materials for production teams"
    },
    {
      "id": "WP-03",
      "title": "Maintenance and reliability enhancement program",
      "owner_role": "Reliability Engineering Manager",
      "duration_quarters": 2,
      "deliverable": "Maintenance plan, preventive maintenance schedule and spare parts stock to support sustained high utilisation"
    },
    {
      "id": "WP-04",
      "title": "Quality and compliance verification",
      "owner_role": "Quality Assurance Manager",
      "duration_quarters": 1,
      "deliverable": "Quality verification report confirming non-conformance reduction and documented corrective actions"
    },
    {
      "id": "WP-05",
      "title": "Performance monitoring and continuous improvement loop",
      "owner_role": "Performance Data Analyst",
      "duration_quarters": 2,
      "deliverable": "Dashboard and weekly gate review pack demonstrating utilisation trend and identified deviations"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Initial gate review: Baseline sign-off",
      "approver_role": "Plant General Manager",
      "criteria": "Accept baseline report, confirm measurement methodology and approve proceeding to control adjustments"
    },
    {
      "gate": "G2",
      "name": "Control change approval",
      "approver_role": "Head of Operations",
      "criteria": "Sign-off on revised procedures and control checklists with documented training and no outstanding critical non-conformance"
    },
    {
      "gate": "G3",
      "name": "Maintenance readiness gate review",
      "approver_role": "VP Manufacturing",
      "criteria": "Approve maintenance plan and spare parts inventory, and confirm resources for reliability enhancements"
    },
    {
      "gate": "G4",
      "name": "Final acceptance and performance sign-off",
      "approver_role": "Chief Operating Officer",
      "criteria": "Accept performance deliverable demonstrating 98% utilisation or documented deviation plan and closure of non-conformances"
    }
  ],
  "compliance_notes": [
    "All activities will follow regulated change control and document control procedures",
    "Any deviation from approved procedures must be recorded as a formal non-conformance and routed for sign-off",
    "Quality records and audit trail will be maintained for each work package deliverable"
  ],
  "risks": [
    {
      "risk": "Insufficient data quality prevents accurate utilisation measurement",
      "mitigation": "Implement data validation in WP-01 and require sign-off on baseline metrics at G1",
      "severity": "high"
    },
    {
      "risk": "Maintenance backlog limits sustained capacity improvements",
      "mitigation": "Prioritise critical items in WP-03 and maintain contingency spares to reduce downtime",
      "severity": "medium"
    },
    {
      "risk": "Operational teams do not adopt new procedures leading to reversion",
      "mitigation": "Deliver targeted training, competency assessments and include procedural control in G2 sign-off",
      "severity": "medium"
    },
    {
      "risk": "Unresolved non-conformances delay final acceptance",
      "mitigation": "Escalation path to VP Manufacturing and Chief Operating Officer with documented corrective actions",
      "severity": "low"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Automate quality data capture from production floor to eliminate manual entry and establish auditable digital traceability",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Assess current data sources and manual entry points",
      "owner_role": "Process Engineering Lead",
      "duration_quarters": 1,
      "deliverable": "Inventory report documenting data sources, manual entry points, data quality metrics and recommended control points"
    },
    {
      "id": "WP-02",
      "title": "Design data capture architecture and interfaces",
      "owner_role": "Industrial IT Architect",
      "duration_quarters": 1,
      "deliverable": "Technical design package including interface specifications, data model, and integration points for automated capture"
    },
    {
      "id": "WP-03",
      "title": "Develop and validate data capture components",
      "owner_role": "Automation Engineering Manager",
      "duration_quarters": 2,
      "deliverable": "Validated software modules and test harness demonstrating end-to-end data capture and non-conformance detection"
    },
    {
      "id": "WP-04",
      "title": "Deploy and configure on production floor equipment",
      "owner_role": "Maintenance Deployment Lead",
      "duration_quarters": 2,
      "deliverable": "Configured equipment on production floor with logged data feed and operational control logs"
    },
    {
      "id": "WP-05",
      "title": "Establish data governance, audit trail and sign-off process",
      "owner_role": "Quality Systems Manager",
      "duration_quarters": 1,
      "deliverable": "Governance procedures, audit trail schema, and formal sign-off checklist for quality assurance"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate review: Requirements and design approval",
      "approver_role": "Plant General Manager",
      "criteria": "Approval of inventory report, technical design package and control points; documented mitigation for identified deviations and acceptance of deliverable scope"
    },
    {
      "gate": "G2",
      "name": "Gate review: Pre-deployment validation",
      "approver_role": "Head of Engineering",
      "criteria": "Successful validation of development modules in test harness, evidence of non-conformance detection and mitigation plans"
    },
    {
      "gate": "G3",
      "name": "Gate review: Operational readiness",
      "approver_role": "Operations Director",
      "criteria": "Deployed components on production floor, operational control logs in place, training completed and documented sign-off on operational readiness"
    },
    {
      "gate": "G4",
      "name": "Gate review: Quality and audit acceptance",
      "approver_role": "Director of Quality",
      "criteria": "Governance procedures approved, audit trail schema validated, and formal sign-off on quality assurance deliverable"
    }
  ],
  "compliance_notes": [
    "All data capture components must retain an auditable trace for regulatory inspection and meet internal quality control requirements",
    "Change control procedures will apply to any configuration or data model modification; deviations must be logged and approved at the gate review"
  ],
  "risks": [
    {
      "risk": "Inaccurate capture of production data leading to incorrect quality records",
      "mitigation": "Implement validation rules, periodic sampling, and reconciliation with manual records; include non-conformance detection and escalation",
      "severity": "high"
    },
    {
      "risk": "Integration failures between legacy equipment and new capture interfaces",
      "mitigation": "Detailed interface design, phased rollout with fallback manual interface, and dedicated integration testing",
      "severity": "medium"
    },
    {
      "risk": "Insufficient user adoption or procedural deviation from automated capture",
      "mitigation": "Training program, clear control instructions, and monitoring with corrective action for deviations",
      "severity": "low"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Reduce raw-data-to-decision latency by 10% through process and tooling controls",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Map current data-to-decision value stream and baseline measurement",
      "owner_role": "Process Engineering Lead",
      "duration_quarters": 1,
      "deliverable": "End-to-end process map, baseline metrics and identified non-conformance points"
    },
    {
      "id": "WP-02",
      "title": "Define control requirements and target architecture for data processing",
      "owner_role": "Data Architect",
      "duration_quarters": 1,
      "deliverable": "Target architecture, control specification and required data schema changes"
    },
    {
      "id": "WP-03",
      "title": "Implement processing improvements and automation controls in production environment",
      "owner_role": "Platform Engineering Manager",
      "duration_quarters": 2,
      "deliverable": "Deployed processing components, automation rules and performance monitoring in production"
    },
    {
      "id": "WP-04",
      "title": "Validate performance, conduct gate review and address deviations",
      "owner_role": "Quality Assurance Lead",
      "duration_quarters": 1,
      "deliverable": "Performance verification report, deviation log with corrective actions and sign-off record"
    },
    {
      "id": "WP-05",
      "title": "Operationalize, train staff and embed controls into operational procedures",
      "owner_role": "Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Operational procedures, training materials and control checklists for ongoing sign-off"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Initiation gate review",
      "approver_role": "Head of Process Excellence",
      "criteria": "Baseline established, scope defined, and initial risk register accepted; proceed to design if metrics demonstrate no critical non-conformance"
    },
    {
      "gate": "G2",
      "name": "Design gate review",
      "approver_role": "Chief Data Officer",
      "criteria": "Target architecture and control specification approved, deviation handling defined, and implementation plan accepted"
    },
    {
      "gate": "G3",
      "name": "Pre-deployment gate review",
      "approver_role": "CTO",
      "criteria": "Performance targets validated in staging, rollback plan and monitoring in place; sign-off required to deploy to production"
    },
    {
      "gate": "G4",
      "name": "Close-out gate review",
      "approver_role": "Head of Quality and Compliance",
      "criteria": "Performance improvement validated to meet 10% reduction, all deviations addressed, and operational procedures approved for sign-off"
    }
  ],
  "compliance_notes": [
    "All changes will follow established change control procedures and be recorded in the configuration management system",
    "Performance measurement methodology must be documented to support audit and traceable sign-off",
    "Any deviation from approved controls must be logged and escalated per non-conformance procedure"
  ],
  "risks": [
    {
      "risk": "Baseline measurement is inaccurate leading to incorrect target setting",
      "mitigation": "Use independent verification of metrics, conservative assumptions and a rapid reassessment in the first gate review",
      "severity": "high"
    },
    {
      "risk": "Processing changes introduce regressions or data quality issues",
      "mitigation": "Implement staged validation in controlled environments, maintain rollback plans and include QA checkpoints in gate reviews",
      "severity": "medium"
    },
    {
      "risk": "Operational resistance to new controls delaying deployment",
      "mitigation": "Engage stakeholders early, provide role-specific training and include control checklists in operational procedures",
      "severity": "low"
    }
  ],
  "timeline_horizon": "6 quarters from initiation to full operationalization with periodic gate reviews"
}

{
  "initiative": "Forecast-to-Plan Handoff Automation",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Requirements and Process Mapping",
      "owner_role": "Planning Process Lead",
      "duration_quarters": 1,
      "deliverable": "Documented process map, control requirements and acceptance criteria for forecast-to-plan handoff"
    },
    {
      "id": "WP-02",
      "title": "Data Model and Interface Specification",
      "owner_role": "Systems Architect",
      "duration_quarters": 1,
      "deliverable": "Technical design and interface specification to enable automated handoff without spreadsheets"
    },
    {
      "id": "WP-03",
      "title": "Integration and Validation Development",
      "owner_role": "Integration Engineer",
      "duration_quarters": 2,
      "deliverable": "Validated integrations and validation tests that produce controlled plan deliverable from forecast inputs"
    },
    {
      "id": "WP-04",
      "title": "Operational Controls and Gate Review Preparation",
      "owner_role": "Compliance & Quality Manager",
      "duration_quarters": 1,
      "deliverable": "Control checklists, sign-off templates and gate review pack for handoff acceptance"
    },
    {
      "id": "WP-05",
      "title": "Deployment, Training and Change Management",
      "owner_role": "Change and Training Lead",
      "duration_quarters": 1,
      "deliverable": "Deployed solution, training records, and change management plan with deviation handling"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Requirements Gate Review",
      "approver_role": "Head of Planning",
      "criteria": "Approve process map and acceptance criteria; no unresolved non-conformance and documented control points"
    },
    {
      "gate": "G2",
      "name": "Design Gate Review",
      "approver_role": "Chief Architect",
      "criteria": "Design passes interface specification and data model; security and compliance controls defined"
    },
    {
      "gate": "G3",
      "name": "Validation Gate Review",
      "approver_role": "Quality & Compliance Director",
      "criteria": "Validation tests pass, integration deliverable accepted, and controls demonstrated for audit"
    },
    {
      "gate": "G4",
      "name": "Operational Readiness Gate Review",
      "approver_role": "Operations Director",
      "criteria": "Operational controls in place, training complete, and sign-off package accepted for production use"
    }
  ],
  "compliance_notes": [
    "Maintain audit trail for every handoff with version-controlled deliverable and gate review records",
    "Ensure data controls and segregation of duties meet regulatory requirements and prevent unauthorized deviation"
  ],
  "risks": [
    {
      "risk": "Data integrity issues between forecast and plan systems",
      "mitigation": "Implement end-to-end validation, checksums and reconciliation reports prior to gate review",
      "severity": "high"
    },
    {
      "risk": "Integration delays due to incompatible legacy systems",
      "mitigation": "Early interface specification, fallback manual handoff procedure and contingency resource allocation",
      "severity": "medium"
    },
    {
      "risk": "Operational resistance to new process causing non-conformance",
      "mitigation": "Stakeholder engagement plan, mandatory training, and documented sign-off to enforce control points",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Automate low-threshold spend approvals within 12 months to replace manual approval chain",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Define policy, thresholds and control requirements",
      "owner_role": "Head of Procurement Policy",
      "duration_quarters": 1,
      "deliverable": "Policy document and threshold matrix as formal work package deliverable for gate review"
    },
    {
      "id": "WP-02",
      "title": "Design automated approval workflow and access controls",
      "owner_role": "Systems Architect",
      "duration_quarters": 1,
      "deliverable": "Design package including workflow diagrams, access control matrix and non-conformance handling rules"
    },
    {
      "id": "WP-03",
      "title": "Develop and test integration with ERP and finance systems",
      "owner_role": "ERP Integration Lead",
      "duration_quarters": 2,
      "deliverable": "Integrated solution with test reports and reconciliation results demonstrating control alignment"
    },
    {
      "id": "WP-04",
      "title": "Pilot deployment and user training with documented sign-off",
      "owner_role": "Procurement Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Pilot report, training records, and formal sign-off from pilot stakeholders"
    },
    {
      "id": "WP-05",
      "title": "Full deployment, change control and monitoring handover",
      "owner_role": "Head of Compliance",
      "duration_quarters": 1,
      "deliverable": "Deployment completion report, change control log, monitoring dashboards and final gate review deliverable"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Policy and Threshold Gate",
      "approver_role": "Chief Procurement Officer",
      "criteria": "Review and sign-off of policy document, threshold matrix and control requirements with no outstanding deviations"
    },
    {
      "gate": "G2",
      "name": "Design and Security Gate",
      "approver_role": "Chief Information Security Officer",
      "criteria": "Approval of workflow design, access control matrix and non-conformance handling rules; security assessment passed"
    },
    {
      "gate": "G3",
      "name": "Pilot Acceptance Gate",
      "approver_role": "Director of Procurement",
      "criteria": "Acceptance of pilot report, training completion evidence and mitigation for any identified deviations"
    },
    {
      "gate": "G4",
      "name": "Deployment Sign-off Gate",
      "approver_role": "Executive Steering Committee",
      "criteria": "Final sign-off on deployment completion, monitoring handover and confirmation that controls meet regulatory requirements"
    }
  ],
  "compliance_notes": [
    "All changes will be documented through formal gate review records and retained for audit trail",
    "Access controls and segregation of duties must meet regulatory access control requirements and be subject to periodic review",
    "Non-conformance handling procedures must be defined and invoked during pilot and deployment with corrective action plans"
  ],
  "risks": [
    {
      "risk": "Integration failures between ERP and finance systems causing delayed approvals",
      "mitigation": "Define minimal viable interfaces, perform end-to-end testing in WP-03 and maintain rollback procedures",
      "severity": "high"
    },
    {
      "risk": "Insufficient user adoption leading to manual bypass of automated approvals",
      "mitigation": "Deliver targeted training, monitor usage metrics in WP-04 and enforce sign-off for any deviation",
      "severity": "medium"
    },
    {
      "risk": "Regulatory or control requirement deviations discovered late in deployment",
      "mitigation": "Engage Compliance early, include regulatory checkpoints in gate reviews and maintain a change control log",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "12 months"
}

{
  "initiative": "Establish predictive maintenance for highest-failure equipment to reduce unplanned downtime and non-conformance events",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Failure Mode Analysis and Prioritisation",
      "owner_role": "Reliability Engineer Lead",
      "duration_quarters": 1,
      "deliverable": "Ranked list of equipment by failure frequency with annotated failure modes and recommended sensors as a work package deliverable"
    },
    {
      "id": "WP-02",
      "title": "Sensor Selection and Data Infrastructure",
      "owner_role": "Instrumentation & Controls Engineer",
      "duration_quarters": 1,
      "deliverable": "Procurement and installation plan for selected sensors and data acquisition network with control integration"
    },
    {
      "id": "WP-03",
      "title": "Model Development and Validation",
      "owner_role": "Data Science Lead",
      "duration_quarters": 2,
      "deliverable": "Validated predictive models with performance metrics and model documentation for gate review sign-off"
    },
    {
      "id": "WP-04",
      "title": "Pilot Deployment and Training",
      "owner_role": "Maintenance Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Pilot deployment on selected equipment, operator training records, and pilot performance report as deliverable"
    },
    {
      "id": "WP-05",
      "title": "Scale-up, Process Controls and Handover",
      "owner_role": "Plant Engineering Director",
      "duration_quarters": 1,
      "deliverable": "Scale-up plan, updated maintenance procedures, control settings and formal handover package for operational sign-off"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Concept and Prioritisation Gate",
      "approver_role": "Head of Reliability",
      "criteria": "Acceptance of ranked equipment list, failure mode analysis and recommended sensors; no unresolved deviations"
